import{_ as a,o as i,c as t,an as n}from"./chunks/framework.CZSJrt3Z.js";const g=JSON.parse('{"title":"Signal Example — ICA 5: Sphering (Whitening)","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/teaching/ica/signal_example_ica_sphering.md","filePath":"tutorials/teaching/ica/signal_example_ica_sphering.md","lastUpdated":null}'),s={name:"tutorials/teaching/ica/signal_example_ica_sphering.md"};function o(l,e,r,h,p,c){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="Signal-Example-—-ICA-5:-Sphering-Whitening" tabindex="-1">Signal Example — ICA 5: Sphering (Whitening) <a class="header-anchor" href="#Signal-Example-—-ICA-5:-Sphering-Whitening" aria-label="Permalink to &quot;Signal Example — ICA 5: Sphering (Whitening) {#Signal-Example-—-ICA-5:-Sphering-Whitening}&quot;">​</a></h1><p>This interactive visualization reveals the hidden mathematical shortcut that makes ICA possible: <strong>Sphering</strong>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">This is Part 5 of the ICA series. It bridges the gap between the correlated mixtures of Part 4 and the optimization search space of Part 6.</p><p></p></div><h2 id="The-Problem" tabindex="-1">The Problem <a class="header-anchor" href="#The-Problem" aria-label="Permalink to &quot;The Problem {#The-Problem}&quot;">​</a></h2><p>If you look at raw EEG mixtures, they form skewed, stretched, off-center blobs. If an algorithm blindly tried to untangle that, it would have to calculate huge mathematical matrices involving stretching, skewing, shifting, and rotating all simultaneously.</p><p>That is too difficult for a fast optimization algorithm.</p><h2 id="The-Solution:-Sphering" tabindex="-1">The Solution: Sphering <a class="header-anchor" href="#The-Solution:-Sphering" aria-label="Permalink to &quot;The Solution: Sphering {#The-Solution:-Sphering}&quot;">​</a></h2><p>Instead of doing everything at once, all modern ICA algorithms apply a standard &quot;Preprocessing&quot; pipeline first called Sphering (or Whitening).</p><p>This demo lets you physically drag the data through these three exact mathematical steps: 2. <strong>Centering</strong>: Subtract the mean value so the data block is physically anchored exactly precisely on <code>(0,0)</code>.</p><ol start="3"><li><p><strong>PCA Rotation</strong>: Run Principal Component Analysis to find the longest arms of the blob, and physically rotate the blob so it aligns securely with the X and Y axes. This removes any cross-correlation.</p></li><li><p><strong>Variance Scaling (Sphering)</strong>: Shrink or stretch the X and Y axes depending on their variance until the entire blob is a perfect mathematical sphere.</p></li></ol><h2 id="Why-Do-We-Do-This?" tabindex="-1">Why Do We Do This? <a class="header-anchor" href="#Why-Do-We-Do-This?" aria-label="Permalink to &quot;Why Do We Do This? {#Why-Do-We-Do-This?}&quot;">​</a></h2><p>Because once the data is transformed into a perfect sphere, the algorithm&#39;s job is over functionally: the only property left to search is <strong>Rotation</strong>.</p><p>By dragging the &quot;Morph&quot; slider all the way to 3.0 (Sphered), you are setting up the perfect circular search space. This directly leads into <a href="./signal_example_ica_optimization">Part 6: Inside the Black Box</a>, where we will simply rotate a line through this sphered data to locate the independent components!</p><h2 id="Code" tabindex="-1">Code <a class="header-anchor" href="#Code" aria-label="Permalink to &quot;Code {#Code}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">signal_example_ica_sphering</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p><a href="./signal_example_ica_geometry">Part 4: 3 Sources &amp; Geometry</a> — Scatter plots and correlation blobs</p></li><li><p><a href="./signal_example_ica_clt">ICA: Central Limit Theorem</a> — Why mixed blobs become Gaussian</p></li><li><p><a href="./signal_example_ica_optimization">Part 6: Inside the Black Box</a> — Gradient ascent rotation</p></li></ul>`,17)])])}const m=a(s,[["render",o]]);export{g as __pageData,m as default};
